from fractions import Fraction
from collections import deque
import math

def can_reach_1(m, n):
    start_numbers = tuple(sorted([Fraction(m, n), Fraction(n, m)]))
    queue = deque([start_numbers])
    visited = set([start_numbers])
    max_numbers = 6
    max_states = 3000
    count = 0
    while queue and count < max_states:
        count += 1
        current_numbers = queue.popleft()
        if Fraction(1, 1) in current_numbers:
            return True
        if len(current_numbers) < max_numbers:
            for i in range(len(current_numbers)):
                for j in range(i + 1, len(current_numbers)):
                    x = current_numbers[i]
                    y = current_numbers[j]
                    a = (x + y) / 2
                    new_numbers_a = tuple(sorted(list(set(current_numbers) | {a})))
                    if new_numbers_a not in visited:
                        visited.add(new_numbers_a)
                        queue.append(new_numbers_a)
                    h = (2 * x * y) / (x + y)
                    new_numbers_h = tuple(sorted(list(set(current_numbers) | {h})))
                    if new_numbers_h not in visited:
                        visited.add(new_numbers_h)
                        queue.append(new_numbers_h)
    return False

results = []
for m in range(1, 25):
    for n in range(1, 25):
        if m == n: continue
        if math.gcd(m, n) == 1:
            if can_reach_1(m, n):
                results.append((m, n))

print(results)

