from fractions import Fraction

def can_reach_one(m, n):
    s = {Fraction(m, n), Fraction(n, m)}
    queue = [tuple(sorted(list(s)))]
    visited = set()
    visited.add(tuple(sorted(list(s))))

    while queue:
        current_s = list(queue[0])
        queue.pop(0)

        if Fraction(1, 1) in current_s:
            return True

        # To limit the search, let's only add numbers if they are "useful"
        # and limit the number of elements in the set.
        if len(current_s) >= 7:
            continue

        for i in range(len(current_s)):
            for j in range(i + 1, len(current_s)):
                x = current_s[i]
                y = current_s[j]

                # Arithmetic mean
                a = (x + y) / 2
                new_s_a = sorted(list(set(current_s + [a])))
                new_s_a_tuple = tuple(new_s_a)
                if new_s_a_tuple not in visited:
                    visited.add(new_s_a_tuple)
                    queue.append(new_s_a_tuple)

                # Harmonic mean
                h = (2 * x * y) / (x + y)
                new_s_h = sorted(list(set(current_s + [h])))
                new_s_h_tuple = tuple(new_s_h)
                if new_s_h_tuple not in visited:
                    visited.add(new_s_h_tuple)
                    queue.append(new_s_h_tuple)
    return False

